"use client";
import * as React from "react";
import { Toaster as Sonner, toast, type ToasterProps } from "sonner";
import { Check, Close, InfoBox, SquareAlert, WarningDiamond } from "pixelarticons/react";
import { cn } from "@/lib/pixel3d";
import { buttonVariants, PixelSpinner } from "@/components/ui/button";

/**
 * Toaster — toasts are crooked stickers that drop onto the lid with a stepped bounce.
 * success = lime, error = tomato, warning = butter, info = sky, default = paper.
 * Fully unstyled sonner: every pixel here is ours.
 *
 *   <Toaster />                  // once, near the root
 *   toast.success("Project submitted")
 */
export { toast };
export type { ToasterProps };

export function Toaster({
  toastOptions,
  icons,
  gap = 20,
  offset = 24,
  position = "bottom-right",
  className,
  ...props
}: ToasterProps) {
  const classNames = toastOptions?.classNames ?? {};
  return (
    <Sonner
      gap={gap}
      offset={offset}
      position={position}
      className={cn("toaster", className)}
      icons={{
        success: <Check className="pixel-icon size-6" aria-hidden />,
        error: <SquareAlert className="pixel-icon size-6" aria-hidden />,
        warning: <WarningDiamond className="pixel-icon size-6" aria-hidden />,
        info: <InfoBox className="pixel-icon size-6" aria-hidden />,
        loading: <PixelSpinner size={24} />,
        close: <Close className="pixel-icon size-4" aria-hidden />,
        ...icons,
      }}
      {...props}
      toastOptions={{
        ...toastOptions,
        unstyled: true,
        classNames: {
          ...classNames,
          toast: cn(
            "toast-sticker flex w-(--width) items-start gap-3 px-5 py-4 font-p3d text-ink",
            classNames.toast
          ),
          // sonner joins classes without merging, so each type sets its own face + tilt
          default: cn("face-paper [--p3d-tilt:-1.2deg]", classNames.default),
          success: cn("face-lime [--p3d-tilt:-2deg]", classNames.success),
          error: cn("face-tomato [--p3d-tilt:1.6deg]", classNames.error),
          warning: cn("face-butter [--p3d-tilt:-1.4deg]", classNames.warning),
          info: cn("face-sky [--p3d-tilt:1.8deg]", classNames.info),
          loading: cn("face-paper [--p3d-tilt:0.8deg]", classNames.loading),
          icon: cn("mt-0.5 grid size-6 shrink-0 place-items-center [&_svg]:pixel-icon", classNames.icon),
          content: cn("flex min-w-0 flex-1 flex-col gap-1", classNames.content),
          title: cn("text-[17px] font-extrabold leading-snug", classNames.title),
          description: cn("text-base font-medium leading-snug text-ink", classNames.description),
          actionButton: cn(buttonVariants({ variant: "ink", size: "sm" }), "shrink-0 self-center [--p3d-tilt:1.5deg]", classNames.actionButton),
          cancelButton: cn(buttonVariants({ variant: "secondary", size: "sm" }), "shrink-0 self-center", classNames.cancelButton),
          closeButton: cn(
            "sticker face-paper peel focus-cut absolute -top-3 -left-3 grid size-7 cursor-pointer place-items-center",
            classNames.closeButton
          ),
        },
      }}
    />
  );
}
Toaster.displayName = "Toaster";

"use client";
import * as React from "react";
import { Slot } from "radix-ui";
import { cva, type VariantProps } from "class-variance-authority";
import { cn, useTilt, type Tilt } from "@/lib/pixel3d";

/**
 * Button — a die-cut sticker that peels on hover and slaps on press.
 * Variants map to inks: primary = pink (act), secondary = paper, success = lime,
 * destructive = tomato, ink = black sticker, ghost = no sticker (text + icon only).
 */
export const buttonVariants = cva(
  "sticker sticker-disabled focus-cut peel inline-flex select-none items-center justify-center gap-2.5 whitespace-nowrap font-p3d font-extrabold tracking-[-0.01em] cursor-pointer [&_svg]:pixel-icon [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        primary: "face-pink",
        secondary: "face-paper",
        success: "face-lime",
        destructive: "face-tomato",
        ink: "face-ink",
        ghost: "[filter:none] before:hidden text-on-lid hover:bg-on-lid/10",
      },
      size: {
        sm: "h-10 px-4 text-base [&_svg]:size-4",
        md: "h-12 px-5 text-lg [&_svg]:size-6",
        lg: "h-14 px-7 text-xl [&_svg]:size-6",
        icon: "size-12 [&_svg]:size-6",
      },
    },
    defaultVariants: { variant: "primary", size: "md" },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
  /** Resting angle. "auto" (default) picks a stable crooked angle; false = straight. */
  tilt?: Tilt;
  /** Shows a pixel spinner and blocks interaction. */
  loading?: boolean;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    { className, variant, size, asChild = false, tilt = "auto", loading = false, style, children, disabled, ...props },
    ref
  ) => {
    const Comp = asChild ? Slot.Root : "button";
    const tiltStyle = useTilt(variant === "ghost" ? false : tilt);
    return (
      <Comp
        ref={ref}
        data-slot="button"
        className={cn(buttonVariants({ variant, size }), className)}
        style={{ ...tiltStyle, ...style }}
        disabled={asChild ? undefined : disabled || loading}
        aria-disabled={asChild && disabled ? true : undefined}
        aria-busy={loading || undefined}
        {...props}
      >
        {loading && !asChild ? (
          <>
            <PixelSpinner />
            {children}
          </>
        ) : (
          children
        )}
      </Comp>
    );
  }
);
Button.displayName = "Button";

/** 8-block pixel spinner; rotates in steps so it reads as pixel art. */
export function PixelSpinner({ className, size = 20, label }: { className?: string; size?: number; label?: string }) {
  return (
    <svg
      viewBox="0 0 10 10"
      width={size}
      height={size}
      role={label ? "status" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      className={cn("pixel-icon animate-[p3d-pixel-spin_800ms_steps(8)_infinite]", className)}
      fill="currentColor"
    >
      <rect x="4" y="0" width="2" height="2" />
      <rect x="7" y="1.5" width="2" height="2" opacity=".85" />
      <rect x="8" y="4" width="2" height="2" opacity=".7" />
      <rect x="7" y="6.5" width="2" height="2" opacity=".55" />
      <rect x="4" y="8" width="2" height="2" opacity=".4" />
      <rect x="1" y="6.5" width="2" height="2" opacity=".3" />
      <rect x="0" y="4" width="2" height="2" opacity=".2" />
      <rect x="1" y="1.5" width="2" height="2" opacity=".12" />
    </svg>
  );
}
